protected void new()
{
    super(classStr(AVAImportWagesService), methodStr(AVAImportWagesService, process), SysOperationExecutionMode::Synchronous);
}

public static AVAImportWagesController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    AVAImportWagesController controller;
    controller = new AVAImportWagesController();
    controller.parmExecutionMode(_executionMode);
    return controller;
}

public static void main(Args _args)
{
    AVAImportWagesController    controller;
    SysOperationStartResult     sysOperationStartResult;
    AVAImportWagesContract      contract;
    LedgerJournalTrans          LedgerJournalTrans;

    controller = AVAImportWagesController::construct();
    controller.parmArgs(_args);

    if (_args && _args.dataset() == tableNum(LedgerJournalTrans))
    {        
        LedgerJournalTrans = _args.record();
    }

    contract = controller.getDataContractObject();
    if (contract is AVAImportWagesContract)
    {
        contract.parmLedgerJournalTable(LedgerJournalTrans.ledgerJournalTable());
    }

    sysOperationStartResult = controller.startOperation();
}

protected void afterOperation(SysOperationExecutionMode _executionMode, AifAsyncResult _asyncResult)
{
    #Task

    super(_executionMode, _asyncResult);

    if (args  &&
        args.caller() is FormRun    &&
        _executionMode == SysOperationExecutionMode::Synchronous)
    {
        args.caller().task(#taskF5);
    }
}

public boolean parmShowDialog(boolean _showDialog = showDialog)
{
    return false;
}
